// fetchAndFindCheckpoint attempts to fetch the metadata branch from remote and find a checkpoint.
// Returns the matching CheckpointID if found, or empty string if not found.
func fetchAndFindCheckpoint(repo *git.Repository, checkpointIDPrefix string) (id.CheckpointID, error) {
	// First check if the checkpoint exists on the remote-tracking branch
	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
	if err != nil {
		// No remote-tracking branch - try fetching
		if fetchErr := FetchMetadataBranch(); fetchErr != nil {
			return "", fetchErr
		}
		// Re-open repo to pick up new refs
		repo, err = openRepository()
		if err != nil {
			return "", err
		}
	} else {
		// Remote-tracking branch exists - check if checkpoint is there before fetching
		checkpointID, parseErr := id.NewCheckpointID(checkpointIDPrefix)
		if parseErr == nil {
			if _, readErr := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path()); readErr != nil {
				return "", fmt.Errorf("checkpoint not on remote: %s", checkpointIDPrefix)
			}
		}
		// Fetch to create/update local branch
		fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
		if fetchErr := FetchMetadataBranch(); fetchErr != nil {
			return "", fetchErr
		}
		repo, err = openRepository()
		if err != nil {
			return "", err
		}
	}

	// Retry listing with fetched data
	store := checkpoint.NewGitStore(repo)
	committed, err := store.ListCommitted(context.Background())
	if err != nil {
		return "", err
	}

	for _, info := range committed {
		if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
			return info.CheckpointID, nil
		}
	}

	return "", fmt.Errorf("checkpoint not found after fetch: %s", checkpointIDPrefix)
}

